// Procedural footstep synthesis — generates the step_* clips the audio
// director cycles (appearance r1: "the world reacts to being walked through").
//
// Why synthesized: the game had NO footstep audio at all, and the asset rule
// is CC0-preferred with provenance in ASSETS.md. Clips generated by this
// script are own work (CC0, in-repo, reproducible): filtered noise bursts +
// a low sine thud, shaped per surface. Four surfaces cover the six bands
// (stone / wet stone / grass / metal), three variants each so no two strides
// read identical even before the director's rate jitter.
//
// Run: node scripts/gen-footsteps.mjs   (writes public/audio/sfx/steps/*.wav)

import { mkdirSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const OUT = join(dirname(fileURLToPath(import.meta.url)), "..", "public", "audio", "sfx", "steps");
mkdirSync(OUT, { recursive: true });

const SR = 22050;

/** Deterministic RNG so the repo's clips are reproducible byte-for-byte. */
function mulberry32(seed) {
  let a = seed >>> 0;
  return () => {
    a |= 0; a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/** 16-bit mono PCM WAV. */
function writeWav(path, samples) {
  // Peak-normalize with headroom; the manifest volume does the mixing.
  let peak = 1e-9;
  for (const s of samples) peak = Math.max(peak, Math.abs(s));
  const k = 0.72 / peak;
  const n = samples.length;
  const buf = Buffer.alloc(44 + n * 2);
  buf.write("RIFF", 0); buf.writeUInt32LE(36 + n * 2, 4); buf.write("WAVE", 8);
  buf.write("fmt ", 12); buf.writeUInt32LE(16, 16); buf.writeUInt16LE(1, 20);
  buf.writeUInt16LE(1, 22); buf.writeUInt32LE(SR, 24); buf.writeUInt32LE(SR * 2, 28);
  buf.writeUInt16LE(2, 32); buf.writeUInt16LE(16, 34);
  buf.write("data", 36); buf.writeUInt32LE(n * 2, 40);
  for (let i = 0; i < n; i++) {
    buf.writeInt16LE(Math.max(-32768, Math.min(32767, Math.round(samples[i] * k * 32767))), 44 + i * 2);
  }
  writeFileSync(path, buf);
}

const sec = (d) => Math.floor(d * SR);
const decay = (i, tau) => Math.exp(-i / (tau * SR));
/** Short linear attack so the transient never clicks. */
const attack = (i, t) => Math.min(1, i / Math.max(1, t * SR));

/** One-pole low-pass over a sample stream (state carried by closure). */
function lp(fc) {
  const a = 1 - Math.exp((-2 * Math.PI * fc) / SR);
  let y = 0;
  return (x) => (y += a * (x - y));
}
/** High-pass = input minus its own low-pass. */
function hp(fc) {
  const f = lp(fc);
  return (x) => x - f(x);
}

/** The heel: a quick downward sine sweep, the body of every footfall. */
function thud(out, rng, { f0 = 105, f1 = 52, dur = 0.07, amp = 1, at = 0 } = {}) {
  const n = sec(dur), o = sec(at);
  let ph = 0;
  for (let i = 0; i < n && o + i < out.length; i++) {
    const t = i / n;
    ph += (2 * Math.PI * (f0 + (f1 - f0) * t)) / SR;
    out[o + i] += Math.sin(ph) * decay(i, dur * 0.35) * attack(i, 0.002) * amp;
  }
}

/** Band-limited noise burst (texture: crunch, swish, splat). */
function burst(out, rng, { dur = 0.06, amp = 1, at = 0, lo = 300, hi = 4000, tau = 0.35 } = {}) {
  const n = sec(dur), o = sec(at);
  const flo = hp(lo), fhi = lp(hi);
  for (let i = 0; i < n && o + i < out.length; i++) {
    out[o + i] += fhi(flo(rng() * 2 - 1)) * decay(i, dur * tau) * attack(i, 0.0015) * amp;
  }
}

/** Decaying sine partial (metal ring). */
function partial(out, { f, dur, amp, at = 0 }) {
  const n = sec(dur), o = sec(at);
  for (let i = 0; i < n && o + i < out.length; i++) {
    out[o + i] += Math.sin((2 * Math.PI * f * i) / SR) * decay(i, dur * 0.3) * attack(i, 0.003) * amp;
  }
}

const SURFACES = {
  // Boot on flagstone: heel thud + short gravelly crunch, a couple of grit ticks.
  stone(rng, v) {
    const out = new Float64Array(sec(0.17));
    thud(out, rng, { f0: 100 + v * 6, f1: 50, dur: 0.065, amp: 1 });
    burst(out, rng, { dur: 0.055, amp: 0.55, lo: 900, hi: 3600 + v * 300 });
    for (let t = 0; t < 2; t++) {
      burst(out, rng, { at: 0.015 + rng() * 0.05, dur: 0.012, amp: 0.3, lo: 1500, hi: 5200 });
    }
    return out;
  },
  // Boot in meadow grass: soft, mostly swish, the thud barely there.
  grass(rng, v) {
    const out = new Float64Array(sec(0.2));
    thud(out, rng, { f0: 88, f1: 46, dur: 0.05, amp: 0.4 });
    burst(out, rng, { dur: 0.13 + v * 0.015, amp: 0.8, lo: 700, hi: 2600, tau: 0.5 });
    burst(out, rng, { at: 0.04, dur: 0.06, amp: 0.35, lo: 1800, hi: 4800, tau: 0.55 });
    return out;
  },
  // Boot on a steel grate: thud + inharmonic ring that hangs a beat.
  metal(rng, v) {
    const out = new Float64Array(sec(0.26));
    thud(out, rng, { f0: 112, f1: 58, dur: 0.055, amp: 0.85 });
    burst(out, rng, { dur: 0.02, amp: 0.5, lo: 2000, hi: 6800 }); // the contact click
    const det = 1 + (v - 1) * 0.035; // per-variant detune, so the grate never loops
    partial(out, { f: 287 * det, dur: 0.2, amp: 0.34 });
    partial(out, { f: 449 * det, dur: 0.15, amp: 0.22 });
    partial(out, { f: 693 * det, dur: 0.1, amp: 0.12 });
    return out;
  },
  // Boot in sewer water: stone thud under a splat — modulated wet noise.
  wet(rng, v) {
    const out = new Float64Array(sec(0.2));
    thud(out, rng, { f0: 96, f1: 50, dur: 0.06, amp: 0.7 });
    // Splat: dense noise whose amplitude flickers fast (droplets, not hiss).
    const n = sec(0.09), fLo = hp(500), fHi = lp(3400);
    let mod = 1;
    for (let i = 0; i < n; i++) {
      if (i % 90 === 0) mod = 0.3 + rng() * 0.7;
      out[i] += fHi(fLo(rng() * 2 - 1)) * decay(i, 0.03) * attack(i, 0.002) * mod * 0.9;
    }
    // One drip lands late — pitch chirp down, quiet.
    const at = sec(0.1 + v * 0.012), dn = sec(0.035);
    for (let i = 0; i < dn && at + i < out.length; i++) {
      const f = 950 - (i / dn) * 600;
      out[at + i] += Math.sin((2 * Math.PI * f * i) / SR) * decay(i, 0.012) * 0.2;
    }
    return out;
  },
};

const VARIANTS = ["a", "b", "c"];
let seed = 0x5eed;
for (const [surface, gen] of Object.entries(SURFACES)) {
  VARIANTS.forEach((tag, vi) => {
    const rng = mulberry32((seed = (seed * 2654435761) >>> 0) ^ vi);
    const path = join(OUT, `step_${surface}_${tag}.wav`);
    writeWav(path, gen(rng, vi));
    console.log("wrote", path);
  });
}
